window.initBoss=function(root){
 'use strict';
 const $=s=>root.querySelector(s),panel=$('#boss-panel'),input=$('#boss-input'),thread=$('#boss-thread'),scroll=$('#boss-scroll'),icon=n=>`<i data-lucide="${n}" aria-hidden="true"></i>`;
 let configured=false,busy=false,history=[],request=null,voiceReplies=true,lastAnswer='',lastFocus=null,keepWakeOnClose=false,phase='idle';
 try{voiceReplies=localStorage.getItem('boss-spoken-replies')!=='off'}catch{}
 const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition,paint=()=>window.lucide?.createIcons();
 const status=(text,kind='')=>{const s=$('#boss-status');s.textContent=text;s.dataset.kind=kind};
 const toBottom=()=>{scroll.scrollTop=scroll.scrollHeight};
 const voice=window.BossVoice.createBossVoice({Recognition,synth:window.speechSynthesis,Utterance:window.SpeechSynthesisUtterance,language:()=> 'en-IN',
  onWake:()=>{voiceReplies=true;syncVoice();openBoss()},
  onQuestion:text=>{openBoss();sendQuestion(text)},
  onDictation:text=>{input.value=(input.value+' '+text).trim().slice(0,4000);status('Dictation captured. Review it, then press Send.');input.focus()},
  onState:s=>{phase=s.phase;panel.classList.toggle('boss-speaking',phase==='speaking');panel.classList.toggle('boss-listening',phase==='listening'||phase==='wake');$('#boss-signal-label').textContent=({idle:'READY WHEN YOU ARE',waiting:'FORMING YOUR ANSWER',speaking:'BOSS IS SPEAKING',listening:'LISTENING TO YOUR QUESTION',wake:'LISTENING FOR “HEY BOSS”'})[phase];$('#boss-dock-status').textContent=phase==='wake'?'Microphone on · Say Hey Boss':phase==='listening'?'Listening · Tap mic to stop':phase==='speaking'?'Speaking your answer':'Ask directly. Learn clearly.';$('#boss-wake').classList.toggle('active',phase==='wake'||phase==='listening');$('#boss-dictate').classList.toggle('active',phase==='listening');$('#boss-wake').setAttribute('aria-label',phase==='wake'?'Stop listening for Boss':'Set up voice activation for Boss');$('#boss-dictate').setAttribute('aria-label',phase==='listening'?'Stop voice conversation':'Talk to Boss');$('#boss-talk').innerHTML=icon(phase==='listening'?'mic-off':'audio-lines')+(phase==='listening'?'Stop listening':'Talk to Boss');if(phase==='wake'){status('Microphone on · Say “Hey Boss” followed by your question');if(panel.open){keepWakeOnClose=true;panel.close()}}else if(phase==='listening')status('Listening · Your spoken question will be sent automatically');else if(phase==='speaking')status('Speaking your answer · Tap the mic to interrupt');else if(phase==='idle'&&!busy)status(configured?'Ready for your next question':'Ask directly. Checking connection…',configured?'ready':'');paint()},
  onError:text=>{status(text,'offline');if(!panel.open)openBoss();message('VOICE NOTICE',text,'notice')}
 });
 function syncVoice(){$('#boss-speak').setAttribute('aria-pressed',String(voiceReplies));$('#boss-speak').setAttribute('aria-label',voiceReplies?'Mute spoken replies':'Enable spoken replies');$('#boss-speak').innerHTML=icon(voiceReplies?'volume-2':'volume-x');paint()}
 function speak(text){if(voiceReplies)voice.speak(text,{resumeAfter:voice.conversation})}
 function inline(parent,text){const regex=/(\*\*[^*\n]+\*\*|`[^`\n]+`|\*[^*\n]+\*)/g;let pos=0;for(const m of text.matchAll(regex)){parent.appendChild(document.createTextNode(text.slice(pos,m.index)));const tag=m[0].startsWith('**')?'strong':m[0].startsWith('`')?'code':'em',n=tag==='strong'?2:1,el=document.createElement(tag);el.textContent=m[0].slice(n,-n);parent.appendChild(el);pos=m.index+m[0].length}parent.appendChild(document.createTextNode(text.slice(pos)))}
 function message(label,text,kind='assistant'){panel.classList.add('boss-has-chat');const el=document.createElement('article');el.className=`boss-message boss-message-${kind}`;const who=document.createElement('strong');who.className='boss-message-label';who.textContent=label;el.appendChild(who);text.split(/```/).forEach((part,i)=>{if(i%2){const pre=document.createElement('pre'),code=document.createElement('code');code.textContent=part.replace(/^[\w#+.-]*\n/,'');pre.appendChild(code);el.appendChild(pre)}else if(part.trim()){const p=document.createElement('p');inline(p,part.trim());el.appendChild(p)}});thread.appendChild(el);toBottom();return el}
 async function checkConnection(){try{const res=await fetch('/api/boss/status',{cache:'no-store'});if(!res.ok)throw Error();const data=await res.json();configured=data.configured===true;$('.boss-privacy').textContent=`AI questions and selected learning context go to ${data.provider||'your AI provider'}. Built-in site guides stay local. Voice may use your browser’s speech service. AI can make mistakes.`;$('#boss-setup').hidden=configured;if(!busy&&!voice.active)status(configured?'Connected · Ask your question directly':'AI connection needed',configured?'ready':'offline')}catch{configured=false;$('#boss-setup').hidden=false;status('Assistant server unavailable. Please restart the local server.','offline')}}
 function openBoss(){if(panel.open)return;lastFocus=document.activeElement;panel.classList.remove('boss-enter');void panel.offsetWidth;panel.classList.add('boss-enter');panel.showModal();input.focus();checkConnection();setTimeout(()=>panel.classList.remove('boss-enter'),600)}
 function closeBoss(){request?.abort();panel.close()}
 panel.addEventListener('close',()=>{request?.abort();if(keepWakeOnClose)keepWakeOnClose=false;else voice.stop();lastFocus?.focus?.()});
 function context(){const c={};if(!$('#boss-context').checked)return c;try{const p=typeof state!=='undefined'?state.profile:null;if(p){c.course=p.course;c.year=p.year;c.domain=p.domain;c.language=p.language}if(typeof page!=='undefined')c.page=page;if(typeof lessonIndex!=='undefined'&&typeof GUIDES!=='undefined'&&p&&GUIDES[p.domain]&&document.querySelector('#modal')?.open)c.lessonTitle=GUIDES[p.domain].lessons[lessonIndex]?.title}catch{}return c}
 async function sendQuestion(raw){let text=String(raw).trim();if(!text||busy)return;if(/^(?:hey\s+)?boss[.!?\s]*$/i.test(text)){input.value='';status('Ready. Ask your question.','ready');if(voiceReplies)voice.speak('I’m listening. Ask your question.',{resumeAfter:voice.conversation});return}text=text.replace(/^(?:hey\s+)?boss[,.!?\s]+/i,'').trim();if(!text)return;if(text.length>4000){status('Please keep your question under 4,000 characters.','error');return}voice.pause();message('YOU',text,'user');input.value='';busy=true;$('#boss-new').disabled=true;request=new AbortController();$('#boss-send').innerHTML=icon('square');$('#boss-send').setAttribute('aria-label','Stop Boss response');panel.classList.add('boss-thinking');status('Working on your question…');paint();
  try{const res=await fetch('/api/boss/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:text,history:history.slice(-12),context:context()}),signal:request.signal});const data=await res.json();if(!res.ok){if(data.error?.code==='AI_NOT_CONFIGURED'){configured=false;$('#boss-setup').hidden=false}throw Error(data.error?.message||'Boss could not answer. Please try again.')}if(!data.reply?.trim())throw Error('No answer was returned. Please try again.');configured=true;lastAnswer=data.reply;history.push({role:'user',content:text},{role:'assistant',content:data.reply.slice(0,6000)});history=history.slice(-12);message(data.answerSource==='site-guide'?'BOSS · VERIFIED SITE GUIDE':'BOSS',data.reply);$('#boss-replay').disabled=false;if(data.incomplete)message('RESPONSE NOTICE','This reply may be incomplete. Ask Boss to continue.','notice');status('Ready for your next question','ready');speak(data.reply)}catch(e){voice.stop();if(e.name==='AbortError')status('Response stopped. Ask again when ready.');else{message('CONNECTION NOTICE',e.message||'Connection failed. Please try again.','notice');status('Could not get an answer. Your learning progress is unchanged.','offline')}}finally{busy=false;request=null;$('#boss-new').disabled=false;$('#boss-send').innerHTML=icon('arrow-up');$('#boss-send').setAttribute('aria-label','Send question to Boss');panel.classList.remove('boss-thinking');paint();toBottom()}
 }
 function talk(){if(phase==='listening'||phase==='wake'){voice.stop();status('Microphone off. You can still type.');return}voiceReplies=true;syncVoice();voice.startConversation()}
 $('#boss-launch').onclick=openBoss;$('#boss-close').onclick=closeBoss;$('#boss-refresh').onclick=checkConnection;
 $('#boss-form').onsubmit=e=>{e.preventDefault();if(busy)request?.abort();else sendQuestion(input.value)};
 $('#boss-send').onclick=e=>{if(busy){e.preventDefault();request?.abort()}};
 input.onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();if(busy)request?.abort();else sendQuestion(input.value)}};
 $('#boss-talk').onclick=talk;$('#boss-dictate').onclick=talk;$('#boss-dictation').onclick=()=>voice.dictate();
 $('#boss-speak').onclick=()=>{voiceReplies=!voiceReplies;try{localStorage.setItem('boss-spoken-replies',voiceReplies?'on':'off')}catch{}syncVoice();if(!voiceReplies){voice.stop();status('Spoken replies muted. Answers will still appear in chat.')}else status('Spoken replies on. Ask a question or play the last answer.','ready')};
 $('#boss-replay').onclick=()=>{if(lastAnswer){voiceReplies=true;syncVoice();voice.speak(lastAnswer,{resumeAfter:false})}};
 $('#boss-new').onclick=()=>{request?.abort();voice.stop();history=[];lastAnswer='';$('#boss-replay').disabled=true;thread.replaceChildren();panel.classList.remove('boss-has-chat');status(configured?'New conversation · Ask directly':'AI connection needed',configured?'ready':'offline');input.focus()};
 $('#boss-guide').onclick=()=>sendQuestion('Explain how I should use NextStep from my profile setup through learning, projects, opportunities, and resume preparation. Give clear short steps.');
 root.querySelectorAll('[data-boss-prompt]').forEach(b=>b.onclick=()=>sendQuestion(b.dataset.bossPrompt));
 $('#boss-wake').onclick=()=>{if(voice.active){voice.stop();status('Microphone off.');return}openBoss();$('#boss-voice-settings').open=true;$('#boss-voice-settings').scrollIntoView({block:'nearest'});status(Recognition?'Enable wake listening below, then say “Hey Boss” and your question.':'Voice recognition is unavailable here. Typing still works.','offline')};
 $('#boss-enable-wake').onclick=()=>{voiceReplies=true;syncVoice();voice.startWake()};
 document.addEventListener('keydown',e=>{if(e.altKey&&e.key.toLowerCase()==='b'){e.preventDefault();if(panel.open)closeBoss();else openBoss()}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden)voice.stop()});window.addEventListener('pagehide',()=>voice.stop());
 if(!Recognition)for(const id of ['boss-enable-wake','boss-dictate','boss-talk','boss-dictation']){$('#'+id).disabled=true;$('#'+id).title='Speech recognition is unavailable in this browser. Type your question instead.'}
 if(!window.speechSynthesis||!window.SpeechSynthesisUtterance){voiceReplies=false;$('#boss-speak').disabled=true;$('#boss-replay').title='Audio playback is unavailable in this browser.'}
 syncVoice();paint();
};
